import{_t as e,it as t,n,rt as r}from"./chunks/framework.C1oW5ckO.js";var i=JSON.parse(`{"title":"Contributing to pumpkin-plugins","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/CONTRIBUTING.md"},"headers":[],"relativePath":"CONTRIBUTING.md","filePath":"CONTRIBUTING.md","lastUpdated":1792029775000}`),a={name:`CONTRIBUTING.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="contributing-to-pumpkin-plugins" tabindex="-1">Contributing to <code>pumpkin-plugins</code> <a class="header-anchor" href="#contributing-to-pumpkin-plugins" aria-label="Permalink to “Contributing to pumpkin-plugins”">​</a></h1><h2 id="set-up" tabindex="-1">Set up <a class="header-anchor" href="#set-up" aria-label="Permalink to “Set up”">​</a></h2><p>Use the Node version in <a href="https://github.com/filiphsps/pumpkin-plugins/blob/master/.node-version" target="_blank" rel="noreferrer"><code>.node-version</code></a> and the pnpm version declared in <a href="package.json"><code>package.json</code></a>, then install the workspace:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><p>Create new components with their generators: <a href="/pumpkin-plugins/guides/creating-a-plugin"><code>pnpm gen</code></a>, <a href="/pumpkin-plugins/guides/creating-an-action"><code>pnpm gen:action</code></a>, or <a href="/pumpkin-plugins/guides/creating-an-extension"><code>pnpm gen:extension</code></a>. For existing components, start with the relevant guide in <a href="https://github.com/filiphsps/pumpkin-plugins/blob/master/docs/README.md" target="_blank" rel="noreferrer"><code>docs/</code></a>.</p><h2 id="make-and-verify-a-change" tabindex="-1">Make and verify a change <a class="header-anchor" href="#make-and-verify-a-change" aria-label="Permalink to “Make and verify a change”">​</a></h2><p>Follow <a href="/pumpkin-plugins/guides/code-style">Code style</a>. Keep unit tests beside the code and integration tests against a real Pumpkin server under the package&#39;s <code>test/</code> directory; see <a href="/pumpkin-plugins/guides/testing">Testing</a>.</p><p>Update docs and READMEs that describe the change. For generated README content, edit its source and run <code>pnpm readme</code>; run <code>pnpm readme:check</code> to check for drift.</p><p>Run the checks that cover your change:</p><ul><li>Code: <code>pnpm lint</code>, <code>pnpm typecheck</code>, and <code>pnpm test</code>.</li><li>Repository metadata and docs: <code>pnpm check</code>.</li><li>Plugin runtime behavior: run the affected package&#39;s integration tests against a real Pumpkin server. <a href="/pumpkin-plugins/guides/testing">Testing</a> has the scoped command.</li></ul><h2 id="open-a-pull-request" tabindex="-1">Open a pull request <a class="header-anchor" href="#open-a-pull-request" aria-label="Permalink to “Open a pull request”">​</a></h2><p>Base the PR on the current <code>master</code> branch and keep it to one topic. Describe what changed and why, list the checks and scenarios you ran, and explain any checks you skipped or that failed. Include the Pumpkin version for integration tests. The <a href="https://github.com/filiphsps/pumpkin-plugins/blob/master/.github/pull_request_template.md" target="_blank" rel="noreferrer">pull request template</a> has the full checklist.</p><p>Use Conventional Commit messages such as <code>feat:</code>, <code>fix:</code>, or <code>docs:</code>. PRs are rebase-merged, so each commit lands as written; see <a href="/pumpkin-plugins/guides/ci-and-releases#merging">CI and releases</a>. The template&#39;s AI-assisted field is for analytics, and the PR author remains responsible for its contents.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};